(x, y, t) => {
  const cx = 240, cy = 120;
  const wx = Math.sin(x*0.018+t*0.3)*18 + Math.cos(y*0.013-t*0.22)*12 + Math.sin((x+y)*0.008+t*0.15)*8;
  const wy = Math.cos(y*0.018-t*0.28)*18 + Math.sin(x*0.015+t*0.32)*12 + Math.cos((x-y)*0.009-t*0.18)*8;
  const sx = x+wx, sy = y+wy;
  const wx2 = Math.sin(sx*0.025-t*0.4)*6 + Math.cos(sy*0.02+t*0.35)*4;
  const wy2 = Math.cos(sy*0.025+t*0.45)*6 + Math.sin(sx*0.022-t*0.3)*4;
  const dx = sx+wx2, dy = sy+wy2;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.9],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.1],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.8],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.2],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.95],
    [80+Math.sin(t*0.7+3)*60, 40+Math.cos(t*0.45+1)*40, 0.14, 2.1, 0.7],
    [400+Math.cos(t*0.55+2)*70, 200+Math.sin(t*0.65+4)*50, 0.11, 1.8, 1.05],
    [200+Math.sin(t*0.25+6)*90, 220+Math.cos(t*0.75)*40, 0.085, 2.4, 0.85]
  ];
  let aS=0, iS=0, harm=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d = Math.sqrt((dx-sX)**2+(dy-sY)**2);
    const wave = Math.sin(d*f-t*sp);
    aS += wave*w;
    iS += Math.sin(d*f*0.7+t*sp*0.6+1.5)*w;
    harm += Math.sin(d*f*1.4-t*sp*0.5+2.0)*w*0.5;
  }
  const n = src.length;
  const act = aS/n, inh = iS/n, hrm = harm/n;
  const bg = (Math.sin(dx*0.04+dy*0.025+t*0.8)+Math.sin(dx*0.03-dy*0.04+t*1.1))/2
    + Math.sin((dx+dy)*0.12+t*2.5)*0.2 + Math.sin((dx-dy)*0.1-t*2)*0.2
    + Math.sin(dx*0.07*dy*0.001+t*0.6)*0.15;
  const dist = Math.sqrt((dx-cx)**2+(dy-cy)**2), ang = Math.atan2(dy-cy, dx-cx);
  const spiral = (Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4
    + Math.sin(dist*0.03-ang*6+t*0.8)*0.2;
  const vortex = Math.sin(ang*5+dist*0.08-t*2)*Math.exp(-dist*0.005)*0.3;
  const reaction = Math.tanh((act-inh*0.65+bg*0.25+spiral+vortex+hrm*0.3)*2.0);
  const cell = Math.tanh((Math.sin(dx*0.15)*Math.sin(dy*0.15)+Math.sin((dx+dy)*0.1+t)*0.5)*1.5)*0.3;
  const micro = Math.sin(dx*0.3+t*3)*Math.sin(dy*0.35-t*2.5)*0.08;
  const blend = reaction*0.65+cell*0.2+micro, v = blend*0.5+0.5;
  const pal = [
    [5,12,52],[10,45,85],[15,90,110],[20,140,130],[45,175,120],
    [130,195,80],[200,185,50],[220,150,55],[210,110,65],[185,70,60],
    [140,40,55],[90,25,50],[50,18,48],[5,12,52]
  ];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const lum = 0.75+Math.sin(reaction*Math.PI)*0.25;
  const edge = Math.abs(reaction)>0.65?1.0+Math.abs(reaction)*0.2:1.0;
  const glow = Math.max(0, 1.0-Math.abs(reaction)*1.5)*0.15;
  return [
    Math.min(255, ((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+glow*60))|0,
    Math.min(255, ((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+glow*80))|0,
    Math.min(255, ((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+glow*120))|0
  ];
}
